cat package.json; cat > bot.mjs <<'EOF'
// Weekly digest text gate. trySend decides; it never sends.
import * as nodeFs from "node:fs";
import * as nodePath from "node:path";

const SMS = "sms";
const WEEKLY_LIMIT = 1; // one digest text per recipient-local week

function stateDir() {
  const dir = process.env.STATE_DIR;
  if (!dir) throw new Error("STATE_DIR is not set");
  nodeFs.mkdirSync(dir, { recursive: true });
  return dir;
}

const enc = (s) => encodeURIComponent(String(s));
const optKey = (userId, channel) => `optout-${enc(userId)}-${enc(channel)}`;
const msgKey = (id) => `digest-msg-${enc(id)}`;

function isOptedOut(dir, userId, channel) {
  const rec = gkRead(dir, optKey(userId, channel));
  return !!(rec && rec.out);
}

function nextWeekStart(ms, zone) {
  const wk = gkWeekKey(ms, zone);
  let t = ms;
  for (let i = 0; i < 9; i++) {
    t = gkNextMidnight(t, zone);
    if (gkWeekKey(t, zone) !== wk) return t;
  }
  return null;
}

export async function trySend({ user, message, now }) {
  const dir = stateDir();
  const refuse = (reason, extra = {}) => ({ sent: false, reason, ...extra });

  if (!user || user.id == null || !message || message.id == null) {
    return refuse("Held: the user or message id is missing, so the digest cannot be checked.");
  }
  const channel = message.channel || SMS;
  const ms = now instanceof Date ? now.getTime() : NaN;
  if (!Number.isFinite(ms)) return refuse("Held: the current time is invalid.");
  if (!gkZoneOk(user.timezone)) {
    return refuse("Held by the time zone rule: the recipient's time zone is missing or invalid, so local time is unknown.");
  }

  if (isOptedOut(dir, user.id, channel)) {
    return refuse(`Held by the opt-out rule: this customer opted out of ${channel} texts.`);
  }

  // Redelivery: one claim per message id, never released once the text may have left.
  if (!gkClaim(dir, msgKey(message.id))) {
    return refuse("Held: this digest event was already handled, so it is not sent twice.");
  }

  // Re-check opt-out after the claim to narrow the race with a concurrent STOP.
  if (isOptedOut(dir, user.id, channel)) {
    gkUnclaim(dir, msgKey(message.id));
    return refuse(`Held by the opt-out rule: this customer opted out of ${channel} texts.`);
  }

  const weekKey = `digest-week-${enc(user.id)}-${enc(channel)}-${gkWeekKey(ms, user.timezone)}`;
  const c = gkCount(dir, weekKey, WEEKLY_LIMIT);
  if (!c.ok) {
    gkUnclaim(dir, msgKey(message.id));
    const next = nextWeekStart(ms, user.timezone);
    return refuse(
      `Held by the weekly limit: this customer already got a digest text this week${next ? `; the next one may go at ${gkFmt(next, user.timezone)}` : ""}.`,
      next ? { nextAllowedAt: new Date(next).toISOString() } : {},
    );
  }

  gkWrite(dir, `digest-sent-${enc(message.id)}`, { userId: user.id, channel, at: ms });
  return { sent: true, reason: "Allowed: customer has not opted out and has had no digest text this week." };
}

export async function optOut(userId, channel = SMS) {
  const dir = stateDir();
  gkWrite(dir, optKey(userId, channel), { out: true, at: Date.now() });
}

export async function handleInbound({ userId, channel = SMS, text, now }) {
  const dir = stateDir();
  if (gkIsStop(text)) {
    gkWrite(dir, optKey(userId, channel), { out: true, at: Date.now() });
    return { action: "opted-out", reply: "You are unsubscribed and will get no more digest texts. Reply START to turn them back on." };
  }
  if (gkIsStart(text)) {
    gkWrite(dir, optKey(userId, channel), { out: false, at: Date.now() });
    return { action: "opted-in", reply: "You are subscribed to the weekly digest again. Reply STOP to unsubscribe." };
  }
  if (gkIsHelp(text)) {
    return { action: "help", reply: "Weekly digest texts. Reply STOP to unsubscribe, START to resubscribe." };
  }
  return { action: "none", reply: null };
}
